<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { ApiError, describeError, downloadFile, formatDate, request, workspacePath, type Workspace } from './api'
import RuntimeEvidenceScope from './RuntimeEvidenceScope.vue'
import type { RuntimeEvidenceScope as Scope } from './runtime-evidence-scope'
import type { OperationsReport, OperationsReportSchedule } from './operations-reports'
import { scenarioCheckOutcomeLabels } from './scenario-checks'
import { readScenarioContext, scenarioContextHref } from './scenario-context'
import { runtimeRuleLabels } from './runtime-findings'
const props=defineProps<{workspace:Workspace}>();const emit=defineEmits<{sessionExpired:[]}>();const base=workspacePath(props.workspace.slug),editor=computed(()=>['owner','operator'].includes(props.workspace.role)),owner=computed(()=>props.workspace.role==='owner')
const context=readScenarioContext(props.workspace.slug)
const scope=ref<Scope>(),valid=ref(false),title=ref(''),reports=ref<OperationsReport[]>([]),schedules=ref<OperationsReportSchedule[]>([]),selected=ref<OperationsReport>(),error=ref(''),notice=ref(''),busy=ref(false),exporting=ref(false),view=ref('analysis'),period=ref<'daily'|'weekly'|'monthly'>('weekly'),scheduleTitle=ref(''),editingSchedule=ref<OperationsReportSchedule>();const active=new AbortController();let detailSequence=0
const periodLabels={daily:'每日',weekly:'每周',monthly:'每月'}
function failed(e:unknown){if(active.signal.aborted)return;if(e instanceof ApiError&&e.status===401)emit('sessionExpired');else error.value=e instanceof Error&&!(e instanceof ApiError)&&!(e instanceof TypeError)?e.message:describeError(e)}
function scopeChanged(value:Scope|undefined,isValid:boolean){scope.value=value;valid.value=isValid}
async function load(){try{const [a,b]=await Promise.all([request<{items:OperationsReport[]}>(base+'/operations-reports',{signal:active.signal}),request<{items:OperationsReportSchedule[]}>(base+'/operations-report-schedules',{signal:active.signal})]);reports.value=a.items;schedules.value=b.items}catch(e){failed(e)}}
async function choose(id:number){const seq=++detailSequence;error.value='';try{const r=await request<OperationsReport>(base+'/operations-reports/'+id,{signal:active.signal});if(seq===detailSequence){selected.value=r;view.value='analysis'}}catch(e){if(seq===detailSequence)failed(e)}}
async function create(){if(!scope.value||!valid.value||!editor.value||busy.value)return;busy.value=true;error.value='';try{const r=await request<OperationsReport>(base+'/operations-reports',{method:'POST',body:JSON.stringify({title:title.value,scope:scope.value}),signal:active.signal});detailSequence++;selected.value=r;view.value='analysis';await load();notice.value='指定范围的运营调查报告已冻结，原始观察、缺口与摘要一并保留。'}catch(e){failed(e)}finally{busy.value=false}}
async function saveSchedule(){if(!scope.value||!valid.value||!owner.value||busy.value)return;busy.value=true;error.value='';try{const {from:_from,to:_to,...dimensions}=scope.value;await request(base+'/operations-report-schedules'+(editingSchedule.value?'/'+editingSchedule.value.id:''),{method:editingSchedule.value?'PUT':'POST',body:JSON.stringify({title:scheduleTitle.value,period:period.value,timezone:'Asia/Shanghai',scope:dimensions,enabled:true,revision:editingSchedule.value?.revision||0}),signal:active.signal});editingSchedule.value=undefined;await load();notice.value='周期报告任务已保存。按上海时区自然日、周或月的窗口生成，实际内容仍受来源与保留范围限制。'}catch(e){failed(e)}finally{busy.value=false}}
async function toggle(schedule:OperationsReportSchedule){if(!owner.value||busy.value)return;busy.value=true;error.value='';try{await request(base+'/operations-report-schedules/'+schedule.id,{method:'PUT',body:JSON.stringify({title:schedule.title,period:schedule.period,timezone:schedule.timezone,scope:schedule.scope,enabled:!schedule.enabled,revision:schedule.revision}),signal:active.signal});await load()}catch(e){failed(e)}finally{busy.value=false}}
async function runSchedule(schedule:OperationsReportSchedule){if(!owner.value||busy.value)return;busy.value=true;error.value='';try{const r=await request<OperationsReport>(base+'/operations-report-schedules/'+schedule.id+'/run',{method:'POST',body:JSON.stringify({revision:schedule.revision}),signal:active.signal});detailSequence++;selected.value=r;view.value='analysis';await load();notice.value='已生成上一完整自然周期的报告，保留窗口不足的部分仍列为证据缺口。'}catch(e){failed(e)}finally{busy.value=false}}
async function exportReport(format:'html'|'json'|'csv'){if(!selected.value||exporting.value)return;exporting.value=true;error.value='';try{await downloadFile(base+'/operations-reports/'+selected.value.id+'/export?format='+format,'operations-report-'+selected.value.id+'.'+format,active.signal)}catch(e){failed(e)}finally{exporting.value=false}}
onMounted(load);onBeforeUnmount(()=>active.abort())
</script>
<template><section class="operations-reports"><div><h2>指定对象与周期运营报告</h2><p>按真实服务、接口、来源内用户引用、IP和时间窗口冻结调查报告。明确已记录观察、技术发现、证据、处置及覆盖缺口，不把无告警当作整体合规通过。</p></div><p v-if="context.assetId||context.activityId">导航范围保留资产{{context.assetId||'未选'}} / 活动{{context.activityId||'未选'}}。本报告按下方明确选择的运行时来源与时间生成；已冻结列表另按每份报告范围核对。</p><p v-if="error" class="message message-error" role="alert">{{error}}</p><p v-if="notice" class="message" role="status">{{notice}}</p><RuntimeEvidenceScope :workspace="workspace" required @change="scopeChanged" @session-expired="emit('sessionExpired')"/>
<form class="panel operations-report-form" @submit.prevent="create"><label>本次报告名称<input v-model="title" maxlength="120" required placeholder="例如：订单服务本周用户访问调查"></label><button class="button button-primary" :disabled="!editor||!scope||!valid||busy">{{busy?'正在生成…':'生成指定范围报告'}}</button></form>
<details class="panel operations-report-form"><summary>周期任务配置与记录 · {{schedules.length}}项</summary><form v-if="owner" @submit.prevent="saveSchedule"><label>周期任务名称<input v-model="scheduleTitle" maxlength="120" required></label><label>报告周期<select v-model="period"><option v-for="(label,key) in periodLabels" :key="key" :value="key">{{label}}（Asia/Shanghai）</option></select></label><p>继承上方的来源、服务、接口、用户引用与IP；开始和结束时间由每次日历周期计算，当前手填日期不用于周期任务。只分析平台已收到的事实。</p><button class="button" :disabled="!scope||!valid||busy">保存周期报告任务</button></form><div v-if="schedules.length" class="table-wrap"><table><thead><tr><th>任务 / 范围</th><th>周期 / 计划</th><th>状态 / 修订</th><th>操作</th></tr></thead><tbody><tr v-for="schedule in schedules" :key="schedule.id"><th scope="row">{{schedule.title}}<small>{{schedule.scope.service}} · 来源 #{{schedule.scope.sourceId}}<template v-if="schedule.scope.subjectRef"> · {{schedule.scope.subjectRef}}</template><template v-if="schedule.scope.clientIp"> · {{schedule.scope.clientIp}}</template></small></th><td>{{periodLabels[schedule.period]}} · {{schedule.timezone}}<small>下次 {{formatDate(schedule.nextRunAt)}}</small></td><td>{{schedule.enabled?'已启用':'已暂停'}} · v{{schedule.revision}}</td><td><div class="actions"><button v-if="owner" class="button" :disabled="busy" @click="toggle(schedule)">{{schedule.enabled?'暂停':'启用'}}</button><button v-if="owner" class="button" :disabled="busy||!schedule.enabled" @click="runSchedule(schedule)">生成上一完整周期</button><button v-if="schedule.lastReportId" class="button" @click="choose(schedule.lastReportId)">最近报告</button></div></td></tr></tbody></table></div><p v-else>尚无周期报告任务。</p></details>
<section class="panel"><div class="panel-heading"><div><h3>已冻结运营报告</h3><p>工作区最近记录，范围以每份报告保存的来源与窗口为准。</p></div><button class="button" :disabled="busy" @click="load">刷新</button></div><p v-if="!reports.length" class="message">尚无运营调查报告。选择真实范围后生成。</p><div v-else class="table-wrap"><table><thead><tr><th>报告</th><th>实际范围</th><th>生成</th><th>操作</th></tr></thead><tbody><tr v-for="report in reports" :key="report.id"><th scope="row">{{report.title}}<small>#{{report.id}}</small></th><td>{{report.scope.service}} · 来源 #{{report.scope.sourceId}}<small>{{formatDate(report.scope.from)}} 至 {{formatDate(report.scope.to)}}</small><small>{{[report.scope.subjectRef,report.scope.clientIp,report.scope.method,report.scope.route].filter(Boolean).join(' · ')}}</small></td><td>{{report.actor}}<small>{{formatDate(report.createdAt)}}</small></td><td><button class="button" @click="choose(report.id)">查看冻结报告</button></td></tr></tbody></table></div></section>
<section v-if="selected" class="panel"><div class="panel-heading"><div><h3>{{selected.title}} · #{{selected.id}}</h3><p>{{selected.scope.service}} · 来源 #{{selected.scope.sourceId}} · {{formatDate(selected.scope.from)}} 至 {{formatDate(selected.scope.to)}}</p></div><div class="actions"><button v-for="format in (['html','json','csv'] as const)" :key="format" class="button" :disabled="exporting" @click="exportReport(format)">导出 {{format.toUpperCase()}}</button></div></div><div class="operations-report-body"><dl class="report-counts"><div><dt>窗口内已记录观察</dt><dd>{{selected.window.total}}</dd></div><div><dt>本报告纳入观察</dt><dd>{{selected.window.items.length}}</dd></div><div><dt>技术判定</dt><dd>{{selected.analysis?.length||0}}</dd></div><div><dt>关联处置</dt><dd>{{selected.actions.length}}</dd></div></dl><p>来源日志保留{{selected.window.retentionDays}}天，每来源最多{{selected.window.retentionLimitPerSource}}条；单份报告最多{{selected.window.limit}}条。{{selected.window.truncated?'本次已截断，超出部分未纳入分析。':'本次未达到报告条数上限。'}}保留窗口外及从未接入的行为未知。</p><ul v-if="selected.missingConditions.length"><li v-for="missing in selected.missingConditions" :key="missing">{{missing}}</li></ul><details v-if="selected.coverage.length||selected.window.warnings.length"><summary>来源覆盖与警告</summary><ul><li v-for="warning in [...selected.coverage,...selected.window.warnings]" :key="warning">{{warning}}</li></ul></details><nav class="report-tabs" aria-label="运营报告内容"><button v-for="item in [{id:'analysis',label:'技术分析'},{id:'observations',label:'实际观察'},{id:'evidence',label:'证据与处置'}]" :key="item.id" class="button" :aria-pressed="view===item.id" @click="view=item.id">{{item.label}}</button></nav>
<template v-if="view==='analysis'"><article v-for="finding in selected.analysis||[]" :key="finding.id" class="report-analysis"><h4>{{finding.title}} · {{scenarioCheckOutcomeLabels[finding.outcome]||finding.outcome}}</h4><p>{{finding.observed}}</p><p>预期：{{finding.expected}}</p><p>依据：{{finding.basis.title}} · {{finding.basis.clause}} · {{finding.basis.version}} · {{finding.ruleVersion}}</p><p>整改建议：{{finding.remediation.advice}}</p><ul v-if="finding.missingConditions.length"><li v-for="missing in finding.missingConditions" :key="missing">{{missing}}</li></ul></article><p v-if="!selected.analysis?.length">这份冻结报告没有技术判定，实际观察和证据仍可核对。</p><h4>已登记风险与检查</h4><ul><li v-for="finding in selected.findings" :key="finding.id"><a :href="scenarioContextHref(workspace.slug,'checks/'+finding.checkId)">{{runtimeRuleLabels[finding.rule]||finding.rule}} · {{finding.method}} {{finding.route}} · 检查 #{{finding.checkId}}</a></li></ul></template>
<div v-else-if="view==='observations'" class="table-wrap"><table><thead><tr><th>时间 / 来源</th><th>方法 / 路由</th><th>主体 / IP</th><th>已观察字段统计</th><th>覆盖</th></tr></thead><tbody><tr v-for="entry in selected.window.items" :key="entry.id"><td>{{formatDate(entry.observation.observedAt)}}<small>{{entry.source}} · {{entry.service}}</small></td><td>{{entry.observation.method}} {{entry.observation.route}}<small>HTTP {{entry.observation.status}}</small></td><td>{{entry.observation.subjectRef||'未记录主体'}}<small>{{entry.observation.clientIp||'未记录IP'}}</small></td><td><span v-for="(field,index) in entry.observation.dataFields||[]" :key="index" class="report-field">{{field.location}} / {{field.name}} · {{field.category}} · {{field.count}}/{{field.observed}}</span></td><td>{{entry.sourceCurrent?'当前来源授权':'来源已变化，历史观察'}}<small>{{entry.observation.captureWarnings?.join('；')}}</small><details v-if="entry.observation.context"><summary>结构化上下文</summary><pre>{{JSON.stringify(entry.observation.context,null,2)}}</pre></details></td></tr></tbody></table></div>
<template v-else><article v-for="evidence in selected.evidence" :key="evidence.id" class="report-analysis"><h4>{{evidence.source}} · {{evidence.record}}</h4><p>{{evidence.scope}} · {{evidence.observedAt?formatDate(evidence.observedAt):'时间未记录'}}</p><small>证据摘要 {{evidence.digest}}</small><details><summary>冻结证据快照</summary><pre>{{JSON.stringify(evidence.snapshot,null,2)}}</pre></details></article><ul><li v-for="action in selected.actions" :key="action.id"><a :href="scenarioContextHref(workspace.slug,'operations/'+action.id)">处置申请 #{{action.id}} · {{action.status}}</a></li></ul></template><small class="report-digest">冻结报告摘要 {{selected.snapshotDigest}}</small><p>本报告用于技术调查与交付辅助，不代表完成正式报送或第三方认证。</p></div></section></section></template>
<style scoped>.operations-reports{display:grid;gap:18px;min-width:0}.operations-reports h2{font-size:18px}.operations-reports h3{font-size:15px}.operations-reports h4{font-size:13px}.operations-reports p,.operations-reports li{font-size:12px;color:var(--secondary);line-height:1.85}.operations-report-form{display:grid;gap:14px;padding:18px 20px}.operations-report-form form{display:grid;gap:14px;padding-block:14px}.operations-report-form label{display:grid;gap:7px;font-size:12px}.operations-report-form input,.operations-report-form select{font:inherit;background:var(--surface);color:var(--ink);padding:9px 10px;border:1px solid var(--input-line);border-radius:6px}.operations-report-form>.button,.operations-report-form form>.button{justify-self:start}.operations-reports table{width:100%;min-width:760px;border-collapse:collapse}.operations-reports th,.operations-reports td{text-align:left;padding:13px;font-size:12px;border-bottom:1px solid var(--line);vertical-align:top}.operations-reports small{font-size:11px;font-weight:400;color:var(--secondary);display:block;margin-top:5px;overflow-wrap:anywhere}.operations-reports summary{font-size:12px;color:var(--accent);cursor:pointer}.operations-reports pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:330px;overflow:auto;font-size:12px}.operations-reports a{color:var(--accent)}.operations-report-body{padding:18px 20px}.report-counts{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px;margin:0}.report-counts dt{font-size:12px;color:var(--secondary)}.report-counts dd{font-size:24px;margin:7px 0}.report-analysis{padding:15px 0;border-bottom:1px solid var(--line)}.report-field{display:block;margin-bottom:5px}.report-tabs,.actions{display:flex;flex-wrap:wrap;gap:8px}.report-tabs{margin-block:18px}.report-tabs [aria-pressed=true]{color:var(--accent);background:var(--accent-soft);border-color:var(--accent)}.report-digest{margin-top:20px}@media(max-width:800px){.report-counts{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>
